import{_ as e,o as l,c as i,ae as r}from"./chunks/framework.RRduUuAx.js";const s=JSON.parse('{"title":"クラウドバックアップと同期","description":"","frontmatter":{},"headers":[],"relativePath":"v1/ja/guide/06-cloud-backup-guide.md","filePath":"v1/ja/guide/06-cloud-backup-guide.md"}'),t={name:"v1/ja/guide/06-cloud-backup-guide.md"};function o(u,a,h,d,n,c){return l(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="クラウドバックアップと同期" tabindex="-1">クラウドバックアップと同期 <a class="header-anchor" href="#クラウドバックアップと同期" aria-label="Permalink to &quot;クラウドバックアップと同期&quot;">​</a></h1><h2 id="📋-概要" tabindex="-1">📋 概要 <a class="header-anchor" href="#📋-概要" aria-label="Permalink to &quot;📋 概要&quot;">​</a></h2><p>クラウドバックアップを有効にすると、同じアカウントでログインした複数端末間でデータを同期できます。</p><hr><h2 id="☁️-クラウドバックアップとは" tabindex="-1">☁️ クラウドバックアップとは？ <a class="header-anchor" href="#☁️-クラウドバックアップとは" aria-label="Permalink to &quot;☁️ クラウドバックアップとは？&quot;">​</a></h2><p>クラウドバックアップは、データをサーバーに保存し、次のことを可能にします。</p><ul><li>端末の紛失・故障時の備え</li><li>複数端末での同期</li><li>新しい端末での復元（ログイン後に同期で再取得）</li></ul><blockquote><p>💡 ヒント：</p><ul><li>クラウドバックアップを使うにはログインが必要です。</li><li>アカウントごとにデータが分離され、本人のみがアクセスできるようになっています。</li></ul></blockquote><h2 id="🔐-ログイン" tabindex="-1">🔐 ログイン <a class="header-anchor" href="#🔐-ログイン" aria-label="Permalink to &quot;🔐 ログイン&quot;">​</a></h2><p>現在は Apple でのログインに対応しています。設定画面上部のユーザーカードからログインしてください。</p><hr><h2 id="🔄-同期のタイミング" tabindex="-1">🔄 同期のタイミング <a class="header-anchor" href="#🔄-同期のタイミング" aria-label="Permalink to &quot;🔄 同期のタイミング&quot;">​</a></h2><ul><li>自動同期：アプリ起動時、データ変更後、帳本切り替え時など</li><li>手動同期：設定画面右上の雲アイコン</li></ul><blockquote><p>⚠️ 注意：手動同期中はアプリを前面で開いたままにしてください。</p></blockquote><h2 id="📊-同期されるもの" tabindex="-1">📊 同期されるもの <a class="header-anchor" href="#📊-同期されるもの" aria-label="Permalink to &quot;📊 同期されるもの&quot;">​</a></h2><p>同期：帳本、明細、口座、カテゴリ、タグ<br> 非同期：アプリ設定（テーマ/言語）、キャッシュ、個人設定</p><hr><h2 id="📌-同期ステータス-目安" tabindex="-1">📌 同期ステータス（目安） <a class="header-anchor" href="#📌-同期ステータス-目安" aria-label="Permalink to &quot;📌 同期ステータス（目安）&quot;">​</a></h2><p>データは状況に応じて、次のような状態で管理されます。</p><ul><li>同期済み</li><li>同期待ち（変更があり、まだ同期していない）</li><li>削除待ち（削除済みで、同期で削除を反映する）</li></ul><hr><h2 id="🔄-競合-同時編集-が起きたら" tabindex="-1">🔄 競合（同時編集）が起きたら <a class="header-anchor" href="#🔄-競合-同時編集-が起きたら" aria-label="Permalink to &quot;🔄 競合（同時編集）が起きたら&quot;">​</a></h2><p>複数端末で同じデータを編集した場合、Koala はできるだけ最新の変更を優先しつつ、まだ同期されていない端末側の変更が上書きされないようにします。</p><hr><p><strong>最終更新</strong>：2026 年 5 月</p>',25)])])}const b=e(t,[["render",o]]);export{s as __pageData,b as default};
